public struct Esse3Answer: Codable, Hashable, Sendable {
    public var applicationId: Int?
    public var answerId: Int?
    public var responseBody: String?

    public init(
        applicationId: Int? = nil,
        answerId: Int? = nil,
        responseBody: String? = nil
    ) {
        self.applicationId = applicationId
        self.answerId = answerId
        self.responseBody = responseBody
    }

    private enum CodingKeys: String, CodingKey {
        case applicationId = "domandaId"
        case answerId = "rispostaId"
        case responseBody = "corpoRisposta"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.applicationId = container.decodeLenient(Int.self, forKey: .applicationId)
        self.answerId = container.decodeLenient(Int.self, forKey: .answerId)
        self.responseBody = container.decodeLenient(String.self, forKey: .responseBody)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(applicationId, forKey: .applicationId)
        try container.encode(answerId, forKey: .answerId)
        try container.encode(responseBody, forKey: .responseBody)
    }
}

